package vectors_test

import (
	"path/filepath"
	"strings"
	"testing"

	"github.com/lennylabs/podium/internal/testharness"
	"github.com/lennylabs/podium/pkg/manifest"
)

// versionFileName is the generated SDK overlay version corpus, beside this
// source.
const versionFileName = "skill-metadata-version.json"

// versionDescription is the description member of the generated corpus.
const versionDescription = "Cross-language corpus for the SDK workspace overlay reading of " +
	"SKILL.md metadata.version (§4.3.4, §6.4). Generated by " +
	"test/vectors/skill_metadata_version_test.go; regenerate with UPDATE_GOLDEN=1 go test ./test/vectors/. " +
	"go_version is the version manifest.ResolveSkillVersion resolves from skill_md with no ARTIFACT.md, " +
	"\"\" when Go resolves no usable version and null when Go does not parse skill_md. " +
	"sdk_version is the version each SDK overlay must report for a SKILL.md-only package: " +
	"the declared reading of a case in the readable form the TypeScript and Python overlays implement, " +
	"and the assigned 0.0.0-auto.0 for every other case."

// versionFile is the layout of skill-metadata-version.json.
type versionFile struct {
	Description string        `json:"description"`
	Cases       []versionCase `json:"cases"`
}

// versionCase is one SKILL.md and the version Go and the SDKs read from it.
// GoVersion is nil, encoded as null, when ParseSkill fails.
type versionCase struct {
	Name       string  `json:"name"`
	SkillMD    string  `json:"skill_md"`
	GoVersion  *string `json:"go_version"`
	SDKVersion string  `json:"sdk_version"`
}

// versionForm is a declared case: a SKILL.md and the version the readable
// form reads from it, "" when the form admits no value. The readable form and
// its numbered conditions are listed beside metadataVersion in
// sdks/podium-ts/src/overlay.ts and _metadata_version in
// sdks/podium-py/podium/_overlay.py.
type versionForm struct {
	name    string
	skillMD string
	reading string
}

// withMetadata returns a SKILL.md whose metadata block holds block, after the
// standard name and description.
func withMetadata(block string) string {
	return skillDoc(skillHead + "metadata:\n" + block)
}

// readableVersionForms are the cases the readable form reads a version from.
// Each case whose SKILL.md Go parses must resolve to that version.
func readableVersionForms() []versionForm {
	return []versionForm{
		{"block plain", withMetadata("  version: 1.0.0\n"), "1.0.0"},
		{"block double-quoted", withMetadata("  version: \"1.0.0\"\n"), "1.0.0"},
		{"block single-quoted", withMetadata("  version: '2.3.4'\n"), "2.3.4"},
		{"block trailing spaces", withMetadata("  version: 1.0.0   \n"), "1.0.0"},
		{"block after a sibling", withMetadata("  owner: alice\n  version: 1.0.0\n"), "1.0.0"},
		{"metadata line with comment", skillDoc(skillHead + "metadata: # build info\n  version: 1.0.0\n"), "1.0.0"},
		{"nested block mapping before version", withMetadata("  requires:\n    bins: lark-cli\n  version: 1.0.0\n"), "1.0.0"},
		{"closed flow sequence before version", withMetadata("  requires:\n    bins: [\"lark-cli\"]\n  version: \"1.0.0\"\n"), "1.0.0"},
		{"closed flow mapping before version", withMetadata("  openclaw: {requires: {bins: [uv]}}\n  version: 1.0.0\n"), "1.0.0"},
		{"closed quoted scalar with doubled quote before version", withMetadata("  note: 'it''s'\n  version: 1.0.0\n"), "1.0.0"},
		{"closed quoted scalar with an escaped quote before version", withMetadata("  note: \"say \\\"hi\\\"\"\n  version: 1.0.0\n"), "1.0.0"},
		{"nested version below a later sibling", withMetadata("  version: 1.0.0\n  build:\n    version: 9.9.9\n"), "1.0.0"},
		{"merge key after version", withMetadata("  version: 1.0.0\n  <<: {version: 2.0.0}\n"), "1.0.0"},
		{"document end after metadata block", withMetadata("  version: 1.0.0\n...\n"), "1.0.0"},
		{"block scalar before metadata",
			skillDoc("name: greet\ndescription: |\n  Greet the user\n  politely\nmetadata:\n  version: 1.0.0\n"), "1.0.0"},
		{"doc example with when_to_use",
			withMetadata("  version: \"1.0.0\"\n  tags: \"finance, close\"\n  when_to_use: |\n    After month-end close\n"), "1.0.0"},
		{"crlf line ends", strings.ReplaceAll(withMetadata("  version: 1.0.0\n"), "\n", "\r\n"), "1.0.0"},
		{"flow form", skillDoc(skillHead + "metadata: {version: \"1.0.0\"}\n"), "1.0.0"},
		{"flow form after a quoted comma", skillDoc(skillHead + "metadata: {owner: \"alice, bob\", version: 1.0.0} # pinned\n"), "1.0.0"},
		{"flow form after an escaped quote", skillDoc(skillHead + "metadata: {note: \"say \\\"hi\\\", bob\", version: 1.0.0}\n"), "1.0.0"},
		{"flow form with a nested mapping",
			skillDoc(skillHead + "metadata: {\"openclaw\": {\"requires\": {\"bins\": [\"uv\"]}}, \"version\": \"1.0.0\"}\n"), "1.0.0"},
	}
}

// unreadableVersionForms are values and layouts outside the readable form.
// The SDK overlays report the assigned version for each, whatever Go
// resolves.
func unreadableVersionForms() []versionForm {
	return []versionForm{
		{"no metadata", skillDoc(skillHead), ""},
		{"top-level version", skillDoc(skillHead + "version: 1.0.0\n"), ""},
		{"non-semver version", withMetadata("  version: \"1.0\"\n"), ""},
		{"version below another child", withMetadata("  build:\n    version: 9.9.9\n  owner: alice\n"), ""},
		{"version under another top-level key", skillDoc(skillHead + "compatibility:\n  version: 4.0.0\n"), ""},
		{"top-level key after the metadata block", withMetadata("  owner: alice\nversion: 3.0.0\n"), ""},
		{"multi-line flow mapping before version", withMetadata("  openclaw: {\n  version: 9.9.9\n  }\n"), ""},
		{"multi-line flow sequence before version", withMetadata("  openclaw: [\n  version: 9.9.9\n  ]\n"), ""},
		{"multi-line double-quoted scalar before version", withMetadata("  note: \"x\n  version: 9.9.9\"\n"), ""},
		{"multi-line single-quoted scalar before version", withMetadata("  note: 'x\n  version: 9.9.9'\n"), ""},
		{"description quoted across metadata",
			skillDoc("name: greet\ndescription: \"foo\nmetadata:\n  version: 9.9.9\nbar\"\n"), ""},
		{"unclosed quote after space in description",
			skillDoc("name: greet\ndescription: say \"hi\nmetadata:\n  version: 1.0.0\n"), ""},
		{"flow form with a comment inside", skillDoc(skillHead + "metadata: {owner: x #, version: 9.9.9}\n  }\n"), ""},
		{"multi-line flow form", skillDoc(skillHead + "metadata: {owner: x,\n  version: 9.9.9}\n"), ""},
		{"flow form with an alias key", skillDoc(skillHead + "metadata: {owner: &k version, version: 1.0.0, *k : 9.9.9}\n"), ""},
		{"flow form two version keys", skillDoc(skillHead + "metadata: {version: 1.0.0, version: 2.0.0}\n"), ""},
		{"flow form mapping under version", skillDoc(skillHead + "metadata: {version: {major: 1}}\n"), ""},
		{"block alias key after version", withMetadata("  owner: &k version\n  version: 1.0.0\n  *k : 9.9.9\n"), ""},
		{"top-level alias key after metadata",
			skillDoc(skillHead + "owner: &m metadata\nmetadata:\n  version: 1.0.0\n*m : {version: 9.9.9}\n"), ""},
		{"two version keys", withMetadata("  version: 1.0.0\n  version: 2.0.0\n"), ""},
		{"plain trailing comment", withMetadata("  version: 1.0.0 # pinned\n"), ""},
		{"value continued on the next line", withMetadata("  version: 1.0.0\n    beta\n"), ""},
		{"tab after colon", withMetadata("  version:\t1.0.0\n"), ""},
		{"mapping under version", withMetadata("  version:\n    major: 1\n  credits:\n    - alice\n"), ""},
		{"sequence under version", withMetadata("  version: [1, 0, 0]\n"), ""},
		{"anchored version", withMetadata("  version: &v 1.0.0\n"), ""},
		{"scalar metadata", skillDoc(skillHead + "metadata: 1.0.0\n"), ""},
		{"empty metadata block", skillDoc(skillHead + "metadata:\n"), ""},
		{"comment directly after the metadata colon", skillDoc(skillHead + "metadata:# info\n  version: 1.0.0\n"), ""},
		{"tab before a flow-form metadata", skillDoc(skillHead + "metadata:\t{version: 1.0.0}\n"), ""},
		{"tab-indented metadata child", skillDoc(skillHead + "metadata:\n\tversion: 1.0.0\n"), ""},
		{"flow form with an entry and no colon", skillDoc(skillHead + "metadata: {owner, version: 1.0.0}\n"), "1.0.0"},
		{"flow form version with no space after the colon", skillDoc(skillHead + "metadata: {version:1.0.0}\n"), ""},
		{"document end before metadata", skillDoc(skillHead + "...\nmetadata:\n  version: 1.0.0\n"), ""},
		{"yaml directive before metadata", skillDoc(skillHead + "%YAML 1.2\nmetadata:\n  version: 1.0.0\n"), ""},
		{"indented first line", skillDoc("  name: x\nmetadata:\n  version: 1.0.0\n"), ""},
		{"lone cr in description", skillDoc("name: greet\ndescription: foo\r  bar\nmetadata:\n  version: 1.0.0\n"), ""},
		{"line separator in description", skillDoc("name: greet\ndescription: foo   bar\nmetadata:\n  version: 1.0.0\n"), ""},
	}
}

// TestSkillMetadataVersionVectors_MatchGo builds every corpus case, resolves
// its SKILL.md through manifest.ParseSkill and manifest.ResolveSkillVersion,
// fails when a readable case that Go parses resolves to a version other than
// its declared reading, and compares the generated corpus with
// test/vectors/skill-metadata-version.json. A case outside the readable form
// may resolve to any version in Go, because the overlay reports none for it.
//
// Spec: §4.3.4
// Spec: §6.4
func TestSkillMetadataVersionVectors_MatchGo(t *testing.T) {
	t.Parallel()
	forms := append(readableVersionForms(), unreadableVersionForms()...)
	cases := make([]versionCase, 0, len(forms))
	names := make([]string, 0, len(forms))
	for _, f := range forms {
		cases = append(cases, versionCaseOf(t, f))
		names = append(names, f.name)
	}
	checkUniqueNames(t, "skill metadata version", names)
	if t.Failed() {
		return
	}
	file := versionFile{
		Description: versionDescription,
		Cases:       sortByName(cases, func(c versionCase) string { return c.Name }),
	}
	testharness.AssertGoldenFile(t, filepath.Join(".", versionFileName), encodeVectors(t, file))
}

// versionCaseOf resolves one declared form and checks a readable form's
// reading against Go.
func versionCaseOf(t testing.TB, f versionForm) versionCase {
	t.Helper()
	c := versionCase{Name: f.name, SkillMD: f.skillMD, SDKVersion: manifest.AutoVersion(0)}
	if f.reading != "" {
		c.SDKVersion = f.reading
	}
	s, err := manifest.ParseSkill([]byte(f.skillMD))
	if err != nil {
		return c
	}
	v := manifest.ResolveSkillVersion(nil, s)
	c.GoVersion = &v
	if f.reading != "" && v != f.reading {
		t.Errorf("%s: Go resolves version %q, but the readable form declares %q", f.name, v, f.reading)
	}
	return c
}
